Bash(1 <<'PS1'
# Supabase CLI on scoop stores credentials in the settings file
$paths = @\(
    "$env:APPDATA\\supabase",
    "$env:LOCALAPPDATA\\supabase", 
    "$env:USERPROFILE\\.supabase",
    "$env:USERPROFILE\\scoop\\persist\\supabase",
    "$env:USERPROFILE\\scoop\\apps\\supabase"
\)
foreach \($p in $paths\) {
    if \(Test-Path $p\) { Write-Host "FOUND: $p"; Get-ChildItem $p -Recurse | ForEach-Object { $_.FullName } }
}
# Also check for settings.json which newer supabase CLIs use
$settingsPath = "$env:USERPROFILE\\AppData\\Roaming\\supabase"
if \(Test-Path $settingsPath\) { Write-Host "Settings: $settingsPath" }
# Check XDG
$xdg = $env:XDG_CONFIG_HOME
if \($xdg\) { Write-Host "XDG: $xdg" }
# Try common linux-like paths under user profile
$linuxPaths = @\("$env:USERPROFILE\\.config\\supabase", "$env:USERPROFILE\\.local\\share\\supabase"\)
foreach \($p in $linuxPaths\) {
    if \(Test-Path $p\) { Write-Host "FOUND: $p"; Get-ChildItem $p -Recurse | ForEach-Object { $_.FullName } }
}
PS1)
